
/* ================= OFFICE v6 additions ================= */
FK[4]=['office/brandkits','Brand Kits','brand'];
const AVPICK=[['#FFB547','#E8B894','#3A2418','#2B63F6','short'],['#FF8A6B','#E9BC98','#3A2418','#13A592','long'],['#A898FF','#8D5A3B','#141414','#16171B','short'],['#5FDCCB','#C68A5E','#1D1A18','#F07C1A','short'],['#FF9CC8','#F1C9A5','#6B3A1E','#7E5BF2','long'],['#9CC8FF','#6E4428','#0F0F0F','#EF5235','long'],['#D3F38A','#E8B894','#B07A3E','#2B5CF0','short'],['#FFD27A','#A86B47','#2A1810','#0EA5A4','long'],['#C3B0FF','#F5D2B8','#8C5A2B','#E9488F','short'],['#7DD3FC','#D9A57B','#3B2A1E','#C99500','long']];
const AVS2={step:1,pick:0,file:null};
const BK=[{id:'l2f',n:'Layer2Funnels',sw:['#16171B','#FFC633','#2B63F6','#F3F1EB'],f:'Bricolage · Geist',main:1},{id:'challenge',n:'Funnel Done Right Challenge',sw:['#F07C1A','#16171B','#FFF3D6'],f:'Bricolage · Inter'},{id:'harry',n:'Harry Kaye PT (client)',sw:['#EF5235','#16171B','#FFFFFF'],f:'Montserrat'}];
let DOCSEC=[['Approved SOPs','sop',['Client onboarding','Brand Base','Strategy','Copy','Build QA']],['Policies','shield',['Leave and holidays','Client data privacy','Tools and passwords']],['Templates','copy',['Proposal','Kick-off deck','Weekly report']]];
let STPL=[['Funnel overview','Name, purpose and business goal.'],['Target audience','Customer avatar, problems, motivations and objections.'],['Offer and value','What you sell and why it matters.'],['Customer journey','From first touch to conversion.'],['Messaging direction','Core message, proof and calls to action.'],['Success criteria','How you’ll know it worked.']];
const _ovOffice=VIEWS.office;
VIEWS.office=p=>{const pg=p[0];
if(pg==='avatars')return oShell('office/avatars',`<div class="ph6"><div><h1 class="t1">Customer Avatars</h1><p class="hint">The people your funnels speak to. Import your research or build one from scratch.</p></div><a class="btn primary sm" href="#/office/avatar-new">${ic('plus',15,'',2.2)}New avatar</a></div><div class="tb6"><label class="inp sm">${ic('search',14)}<input placeholder="Search avatars" data-filter></label>${vsw([['active','Active'],['arch','Archived'],['all','All']],'active','noop')}</div>
<div class="avgrid">${AVS().map(a=>`<a class="avcard" href="#/office/avatar/${a.id}" data-row="${a.n}" style="--c:${a.c}"><span class="avc-art">${figure(a)}<span class="avc-badge">${a.v} · ${a.stat}</span></span><span class="avc-body"><b>${a.n.split(',')[0]}</b><small>${a.n.split(', ')[1]||''}</small><span class="avc-role">${a.role}</span><span class="avc-foot"><span class="ring xs" style="--v:${a.done};--rc:${a.c}"></span>${a.done}% complete<span class="grow"></span>${a.upd}</span></span></a>`).join('')}<a class="avcard add" href="#/office/avatar-new">${ic('plus',26)}<b>New avatar</b><small>Import a Word or PDF, or start blank</small></a></div>`,[['Office'],['Funnels','office/funnels'],['Customer Avatars']]);
if(pg==='avatar-new')return avatarNew();
if(pg==='avatar'&&p[2]==='edit')return avatarEdit(AVS().find(x=>x.id===p[1])||AVS()[0],p[3]);
if(pg==='offer-new')return offerNew();
if(pg==='story-new')return storyNew();
if(pg==='brandkits')return oShell('office/brandkits',`<div class="ph6"><div><h1 class="t1">Brand Kits</h1><p class="hint">One kit per brand: ${oname()}, each product line, or a client you manage.</p></div><a class="btn primary sm" href="#/office/brandkit-new">${ic('plus',15,'',2.2)}New brand kit</a></div><div class="cardgrid">${BK.map(k=>`<a class="card6 bkc" href="#/office/brandkit/${k.id}"><span class="bk-sw">${k.sw.map(c=>`<i style="--c:${c}"></i>`).join('')}</span><b>${k.n}${k.main?' <span class="pill" style="height:20px">Main</span>':''}</b><small class="muted">${k.f}</small></a>`).join('')}<a class="card6 bkc add" href="#/office/brandkit-new">${ic('plus',24)}<b>New brand kit</b></a></div>`,[['Office'],['Funnels','office/funnels'],['Brand Kits']]);
if(pg==='brandkit'){const k=BK.find(x=>x.id===p[1])||BK[0];return oShell('office/brandkits',`${back('office/brandkits','Brand Kits')}<div class="ph6" style="margin-top:8px"><h1 class="t1">${k.n}</h1><div class="acts"><button class="btn ghost sm" data-act="toast:Duplicated.:ok">${ic('copy',15)}Duplicate</button><a class="btn ink sm" href="#/office/brandkit-new">${ic('edit',15)}Edit</a></div></div>${brandKit()}`,[['Office'],['Brand Kits','office/brandkits'],[k.n]])}
if(pg==='brandkit-new')return brandkitNew();
if(pg==='strategy-template')return oShell('office/strategies',`${back('office/strategies','Funnel Strategies')}<div class="ph6" style="margin-top:8px"><div><h1 class="t1">Default strategy template</h1><p class="hint">The headings every new funnel strategy starts with. Existing documents never change.</p></div><button class="btn primary sm" data-act="toast:Template saved as v4. New strategies use it from now on.:ok">Save template</button></div><div class="split"><section class="card6"><header><h2>Sections</h2><button class="lk" data-act="tpladd">${ic('plus',13)}Add section</button></header><div class="stg-edit pad-s">${STPL.map(([h,d],i)=>`<div class="stg-row"><span class="grip">${ic('grip',14)}</span><b class="num">${i+1}</b><div style="flex:1;display:grid;gap:6px"><input value="${h}" aria-label="Heading"><input value="${d}" aria-label="Helper text" class="sm-in"></div><button class="iconbtn xs" aria-label="Remove" data-act="tpldel:${i}">${ic('trash',14)}</button></div>`).join('')}</div></section><aside class="stackcol"><section class="card6 pad-s"><p class="sec-t" style="margin-top:0">Preview</p><div class="tplprev">${STPL.map(([h,d])=>`<b>${h}</b><small>${d}</small>`).join('')}</div></section><section class="card6 pad-s"><p class="sec-t" style="margin-top:0">${ic('hist',14)}Versions</p><p class="hint">v3 · 2 Nov · Tabish<br>v2 · 12 Oct · Usman</p></section></aside></div>`,[['Office'],['Funnel Strategies','office/strategies'],['Template']]);
if(pg==='strategies'){const h=_ovOffice(p);return h.replace('<a class="btn primary sm" href="#/office/strategy/new">','<a class="btn ghost sm" href="#/office/strategy-template">'+ic('sliders',15)+'Default template</a><a class="btn primary sm" href="#/office/strategy/new">')}
if(pg==='documents')return oShell('office/documents',`<div class="ph6"><div><h1 class="t1">Documents</h1><p class="hint">${oname()}’s handbook. Make a section for anything your team needs to find.</p></div><div class="acts"><a class="btn ghost sm" href="#/drive/home">${plate(app('drive'),18)}Open Drive</a><button class="btn primary sm" data-act="docsec">${ic('plus',15,'',2.2)}New section</button></div></div>${DOCSEC.map(([t,i,L],si)=>`<section class="card6 docsec"><header><h2>${ic(i,17)} ${t}</h2><span class="cnt">${L.length}</span><span class="grow"></span><button class="btn quiet sm" data-act="toast:New document opens in the editor.">${ic('plus',14)}New document</button><button class="btn quiet sm" data-act="toast:Upload Word, PDF, Excel or images.">${ic('upload',14)}Upload</button><button class="iconbtn xs" aria-label="Section menu" data-act="toast:Rename · Move · Who can see · Delete section">${ic('more',14)}</button></header><div class="docrow">${L.map((n,j)=>`<a class="docc" href="#/drive/edit/doc/sop">${docIc(si*3+j,32)}<span><b>${n}</b><small>${si===0?'Owner protected · ':''}Word · updated ${['today','2 days ago','last week'][j%3]}</small></span></a>`).join('')}<button class="docc drop" data-act="toast:Drop files to upload into ${t}.">${ic('upload',18)}<span>Drop Word or PDF files</span></button></div></section>`).join('')}`,[['Office'],['Documents']]);
if(pg==='settings')return oShell('office/home',`<div class="ph6"><h1 class="t1">Notification settings</h1></div>${notifSettings()}`,[['Office'],['Notifications']]);
if(pg==='admin')return adminPage(p[1]||'people');
const h=_ovOffice(p);
if(pg==='offers')return h.replace(`data-act="toast:New offer opens the editor."`,`data-act="nav:office/offer-new"`);
if(pg==='stories')return h.replace(`data-act="toast:New story opens the editor."`,`data-act="nav:office/story-new"`);
return h};
function notifSettings(){return `<div class="tbl6"><div class="thd"><span>App</span><span>In-app inbox</span><span>Email digest</span><span>Mentions</span><span>Approvals</span><span></span></div>${['projects','tasks','clients','planner','drive','social','forms','agents'].map(a=>`<div class="tr"><span class="t1c">${plate(app(a),24)}<b>${app(a).name}</b></span><span><button class="toggle" role="switch" aria-checked="true" data-act="tgl" aria-label="In app"></button></span><span><select class="sel sm"><option>Daily</option><option>Never</option><option>Instantly</option></select></span><span class="tx2">Always</span><span class="tx2">Always</span><span></span></div>`).join('')}</div><p class="hint" style="margin-top:8px">Email needs an approved provider. Mentions and approvals can’t be turned off.</p>`}
/* ---------- New avatar: import or start blank, pick a 3D avatar ---------- */
function avatarNew(){const s=AVS2.step;const steps=['Start','Read the file','Check the sections','Choose a look','Name it'];let b='';
if(s===1)b=`<div class="grid2"><button class="startc" data-act="avstep:2">${ic('upload',30)}<b>Import a Word or PDF</b><small>We read your research and sort it into the avatar’s chapters. You check everything before it’s saved.</small><span class="drop6">Drop .docx or .pdf here · up to 20 MB</span></button><button class="startc" data-act="avstep:4">${ic('edit',30)}<b>Start blank</b><small>Choose a look, give it a name, then fill chapters at your own pace.</small></button></div>`;
if(s===2)b=`<div class="proc"><span class="docic" style="--c:#2B63F6;width:56px;height:56px">${ic('doc',28)}</span><b>Dream_Customer_Avatar_John_v1.docx</b><small class="muted">2,496 words · 11 sections found</small><div class="lp-steps">${['Reading the document','Finding sections and tables','Matching them to chapters'].map((x,i)=>`<span class="${i<2?'ok':'now'}">${i<2?ic('check',14,'',2.6):'<i class="spin"></i>'}${x}</span>`).join('')}</div><span class="prog" style="--v:72%;width:320px"><i></i></span><button class="btn primary sm" data-act="avstep:3">Continue</button><p class="hint">Prototype: the reading step needs the backend (document parsing). Nothing leaves ${oname()}.</p></div>`;
if(s===3)b=`<p class="tx2" style="margin-bottom:12px">Each part of your file is matched to a chapter. Change any match, or keep text as a custom section.</p><div class="tbl6"><div class="thd"><span>From your file</span><span>Goes to chapter</span><span>Confidence</span><span>Items</span><span></span><span></span></div>${[['1. THE MARKET MAP','Market map','High',3],['2. QUALIFICATION','Qualification','High',3],['3. AVATAR — BASIC PROFILE','Basic profile','High',7],['4. WHAT DRIVES HIM','What drives him + Beliefs','High',14],['5. EXTERNAL vs INTERNAL DESIRES','Desires','High',8],['6. BEST vs WORST CUSTOMER','Best vs worst customer','High',15],['7. ONE-LINE NICHE STATEMENT','Niche statement','High',2],['8. WHAT TO DO NEXT','What to do next','Medium',6],['10. IMPORTANT CONTEXT NOTES','Context notes','Medium',1],['11. CURRENT AND FUTURE PROBLEMS','Problems, now and next','Medium',12],['Russell’s vocabulary list','New section: Vocabulary','Low',9]].map(([f,c,cf,n])=>`<div class="tr"><span class="t1c"><b>${f}</b></span><span><select class="sel sm"><option>${c}</option><option>Custom section</option><option>Skip</option></select></span><span><span class="pill ${cf==='High'?'blue':cf==='Medium'?'warn':''}">${cf}</span></span><span>${n}</span><span></span><span></span></div>`).join('')}</div><div class="tb6" style="margin-top:12px"><span class="grow"></span><button class="btn quiet sm" data-act="avstep:1">Back</button><button class="btn primary sm" data-act="avstep:4">Looks right</button></div>`;
if(s===4)b=`<p class="tx2" style="margin-bottom:12px">Pick the 3D avatar that feels like this customer. You can change it later.</p><div class="pickgrid">${AVPICK.map((x,i)=>`<button class="pick ${AVS2.pick===i?'on':''}" data-act="avpick:${i}" aria-pressed="${AVS2.pick===i}" style="--c:${x[0]}"><span class="avc-art sm">${figure({id:'pk'+i,c:x[0],skin:x[1],hair:x[2],shirt:x[3],hs:x[4]})}</span></button>`).join('')}</div><div class="tb6" style="margin-top:14px"><span class="grow"></span><button class="btn quiet sm" data-act="avstep:1">Back</button><button class="btn primary sm" data-act="avstep:5">Next</button></div>`;
if(s===5){const x=AVPICK[AVS2.pick];b=`<div class="split"><section class="card6 pad-s"><div class="row2"><div class="field"><label>Avatar name <i class="req">*</i></label><input value="John"></div><div class="field"><label>Short description</label><input value="the One Comma Club chaser"></div></div><div class="row2"><div class="field"><label>Role</label><input value="Course creator · coach · consultant"></div><div class="field"><label>Market</label><select><option>Wealth</option><option>Health</option><option>Relationships</option></select></div></div><div class="field"><label>Used for</label><select><option>${oname()} (internal)</option><option>A client: Harry Kaye PT</option></select></div><div class="tb6"><span class="grow"></span><button class="btn quiet sm" data-act="avstep:4">Back</button><button class="btn primary sm" data-act="avcreate">Create avatar</button></div></section><aside class="card6 pad-s" style="text-align:center"><span class="avc-art" style="--c:${x[0]};display:block;max-width:220px;margin:0 auto">${figure({id:'pkf',c:x[0],skin:x[1],hair:x[2],shirt:x[3],hs:x[4]})}</span><b style="font:700 22px var(--font-d)">John</b><p class="hint">${AVS2.file!==false?'11 chapters filled from your file':'Empty chapters ready to fill'}</p></aside></div>`}
return `<div class="studio-wrap" style="--c:#FFB547">${focusBar('office',{title:'<b>New customer avatar</b>',sub:'Office › Funnels › Customer Avatars',back:'office/avatars'})}<div class="studio-body narrow"><ol class="wizsteps">${steps.map((x,i)=>`<li class="${i+1<s?'done':i+1===s?'now':''}">${i+1<s?ic('check',13,'',2.6):i+1}<span>${x}</span></li>`).join('')}</ol>${b}</div></div>`}
/* ---------- Avatar edit mode: edit any chapter, heading or line; add sections ---------- */
function avatarEdit(a,ch){const P=JOHN;const C=[['market','Market map'],['qual','Qualification'],['basic','Basic profile'],['drives','What drives him'],['beliefs','Beliefs'],['desires','Desires'],['filter','Best vs worst'],['problems','Problems'],['niche','Niche statement'],['next','What to do next'],['notes','Context notes']];const k=ch||'beliefs';
const ed=k==='beliefs'?`<div class="edtable">${P.beliefs.map(([w,b,v])=>`<div class="edr"><span class="grip">${ic('grip',14)}</span><input value="${w}" class="sm-in" style="width:110px"><input value="${b}"><select class="sel sm"><option ${v==='T'?'selected':''}>True · honour it</option><option ${v==='F'?'selected':''}>False · break gently</option><option>Cultural</option></select><button class="iconbtn xs" aria-label="Remove">${ic('trash',14)}</button></div>`).join('')}<button class="addrow">${ic('plus',14)}Add belief</button></div>`:k==='basic'?`<div class="edtable">${P.facts.map(([f,v])=>`<div class="edr"><input value="${f}" class="sm-in" style="width:160px"><input value="${v}"><label class="chk"><input type="checkbox" checked> Show on profile</label><button class="iconbtn xs">${ic('trash',14)}</button></div>`).join('')}<button class="addrow">${ic('plus',14)}Add field</button></div>`:`<div class="rte"><div class="ed-tools in">${['bold','italic','ul','link'].map(i=>`<button>${ic(i,16)}</button>`).join('')}</div><div contenteditable="true" class="rte-b"><p>${(P[{drives:'wants',desires:'ext',niche:'wants',next:'wants',notes:'wants',filter:'wants',problems:'wants',market:'wants',qual:'wants'}[k]]||[]).map(x=>Array.isArray(x)?x[0]:x).join('</p><p>')}</p></div></div>`;
return `<div class="studio-wrap" style="--c:${a.c}">${focusBar('office',{title:`<b>Editing: ${a.n}</b>`,sub:'Changes update the profile and the full profile together',back:'office/avatar/'+a.id,right:`<span class="savest dirty" id="savest"><i></i>Unsaved changes</span><a class="btn quiet sm" href="#/office/avatar/${a.id}">Cancel</a><button class="btn primary sm" data-act="avsave:${a.id}">Save</button>`})}<div class="studio-body"><div class="deep"><nav class="chapters"><p class="over">Chapters</p>${C.map(([kk,l])=>`<a href="#/office/avatar/${a.id}/edit/${kk}" ${kk===k?'aria-current="page"':''}><span class="grip">${ic('grip',12)}</span>${l}</a>`).join('')}<button class="addrow" data-act="avaddsec">${ic('plus',14)}Add chapter</button></nav><div><div class="edhead"><input class="tp-title" value="${C.find(c=>c[0]===k)[1]}" aria-label="Chapter heading"><label class="chk"><input type="checkbox" checked> Show a summary on the profile</label><button class="iconbtn" aria-label="Chapter menu" data-act="toast:Move · Duplicate · Delete chapter">${ic('more',16)}</button></div><p class="hint" style="margin:-4px 0 12px">Edit text directly. Rows can be dragged to reorder.</p>${ed}<div class="notice plain" style="margin-top:14px">${ic('refresh',16)}<span>The profile shows a summary of this chapter. It updates as soon as you save; there is only one copy of the data.</span></div></div></div></div></div>`}
function offerNew(){return `<div>${focusBar('office',{title:'<b>New offer or product</b>',sub:'Office › Funnels › Offers & Products',back:'office/offers',right:`<button class="btn quiet sm" data-act="nav:office/offers">Cancel</button><button class="btn ghost sm" data-act="toast:Saved as draft.:ok">Save draft</button><button class="btn primary sm" data-act="toast:Offer created.:ok">Create offer</button>`})}<div class="formpage"><div class="formcol">
${[['Basics',`<div class="field"><label>Name <i class="req">*</i></label><input placeholder="e.g. Funnel Done-For-You"></div><div class="row2"><div class="field"><label>Type</label><select><option>Service</option><option>Course</option><option>Coaching</option><option>Digital product</option><option>Physical product</option></select></div><div class="field"><label>Status</label><select><option>Draft</option><option>Active</option></select></div></div><div class="field"><label>Promise (one line)</label><input placeholder="A finished funnel that books calls, in 30 days."></div>`],['Price and terms',`<div class="row2"><div class="field"><label>Price</label><input placeholder="3,000"></div><div class="field"><label>Currency</label><select><option>USD</option><option>GBP</option><option>PKR</option></select></div></div><div class="seg3">${['One-off','Recurring','Payment plan'].map((l,i)=>`<button aria-checked="${!i}" data-act="noop">${l}</button>`).join('')}</div><div class="row2"><div class="field"><label>Guarantee</label><input placeholder="30 days of fixes"></div><div class="field"><label>Delivery time</label><input placeholder="30 days"></div></div>`],['What’s included',`<div class="edtable">${['Strategy and avatar research','All copy written for you'].map(x=>`<div class="edr"><span class="grip">${ic('grip',14)}</span><input value="${x}"><button class="iconbtn xs">${ic('trash',14)}</button></div>`).join('')}<button class="addrow">${ic('plus',14)}Add item</button></div><div class="field"><label>Bonuses</label><input placeholder="Optional"></div>`],['Who it’s for',`<div class="field"><label>Customer avatars</label><div class="chipsel">${AVS().map((a,i)=>`<button class="chip ${!i?'on':''}" data-act="chipt" aria-pressed="${!i}">${a.n.split(',')[0]}</button>`).join('')}</div></div><div class="field"><label>Value Ladder step</label><select><option>Not on a ladder</option><option>Core offer</option></select></div>`],['Internal notes',`<div class="field"><textarea placeholder="Never shared with clients"></textarea></div>`]].map(([h,c],i)=>`<section class="fsec6"><h3><span>${i+1}</span>${h}</h3>${c}</section>`).join('')}</div><aside class="formprev"><p class="over">Preview</p><div class="card6 pad-s" style="background:linear-gradient(140deg,color-mix(in srgb,#FFC633 20%,var(--surface)),var(--surface))"><b style="font:700 20px var(--font-d)">Funnel Done-For-You</b><p style="font:italic 16px 'Newsreader',serif">A finished funnel that books calls, in 30 days.</p><b class="mono" style="font-size:28px">$3,000</b><small class="muted">One-off · Service</small></div></aside></div></div>`}
function storyNew(){return `<div>${focusBar('office',{title:'<b>New story</b>',sub:'Office › Funnels › Stories',back:'office/stories',right:`<button class="btn quiet sm" data-act="nav:office/stories">Cancel</button><button class="btn primary sm" data-act="toast:Story saved.:ok">Save story</button>`})}<div class="formpage"><div class="formcol">${[['The story',`<div class="seg3">${['Case study','Testimonial','Origin story'].map((l,i)=>`<button aria-checked="${!i}" data-act="noop">${l}</button>`).join('')}</div><div class="field"><label>Headline <i class="req">*</i></label><input placeholder="From 0 to 41 booked calls"></div><div class="field"><label>Who is it about?</label><select><option>A client: Harry Kaye PT</option><option>${oname()}</option></select></div><div class="field"><label>The story</label><textarea rows="5"></textarea></div>`],['Before → after',`<div class="row2"><div class="field"><label>Before</label><input placeholder="2 calls a week"></div><div class="field"><label>After</label><input placeholder="41 calls in 30 days"></div></div><div class="field"><label>Best quote</label><input placeholder="“It finally sounds like me.”"></div>`],['Permission',`<div class="seg3">${['Consent given','Ask consent','Anonymous only'].map((l,i)=>`<button aria-checked="${!i}" data-act="noop">${l}</button>`).join('')}</div><button class="btn ghost sm" style="margin-top:8px">${ic('upload',14)}Attach consent (email or form)</button>`],['Where to use it',`<div class="chipsel">${['Sales page','Emails','Ads','Webinar','Checkout'].map(l=>`<button class="chip" data-act="chipt" aria-pressed="false">${l}</button>`).join('')}</div>`]].map(([h,c],i)=>`<section class="fsec6"><h3><span>${i+1}</span>${h}</h3>${c}</section>`).join('')}</div></div></div>`}
