const _avStudio=avatarStudio;avatarStudio=function(p,tab,list,base){let h=_avStudio(p,tab,list,base);h=h.replace(`data-act="toast:Every section becomes editable, with Save and Cancel."`,`data-act="nav:office/avatar/${p.id}/edit"`);
if(tab==='profile')h=h.replace('<div class="oneliner">',`<button class="addsec" data-act="avaddsec">${ic('plus',16)}Add a section to the profile</button><div class="oneliner">`);
if(tab==='deep')h=h.replace(/<h2>(\d+\. [^<]+)<\/h2>/g,(m,t)=>`<h2>${t}<a class="iconbtn xs chedit" href="#/office/avatar/${p.id}/edit" aria-label="Edit ${t}">${ic('edit',14)}</a></h2>`);
if(tab==='use')h=h.replace('<p class="lede" style="margin:-6px 0 18px">',`<p class="lede" style="margin:-6px 0 18px"><b>Use it</b> turns the research into ready copy angles. Each card says which chapter it comes from; “Add to strategy” drops it into a funnel strategy document. `);
if(tab==='evidence')h=h.replace('<div class="split">',`<p class="lede" style="margin:-6px 0 14px"><b>Evidence</b> shows how sure you can be: which parts come from real interviews or data, and which are still guesses.</p><div class="split">`);
return h};
